// GET /api/changelog?limit=&user=&area= — newest first
app.get('/api/changelog', async (req, res) => {
  if (!pool) return res.json([]);
  try {
    await ensureLogTable();
    const lim = Math.min(parseInt(req.query.limit) || 300, 500);
    const conds = [], vals = [];
    if (req.query.user) { vals.push(req.query.user); conds.push('username = $' + vals.length); }
    if (req.query.area) { vals.push(req.query.area); conds.push('area = $' + vals.length); }
    vals.push(lim);
    const r = await pool.query(
      'SELECT id, ts, username, area, action, details FROM change_log' +
      (conds.length ? ' WHERE ' + conds.join(' AND ') : '') + ' ORDER BY id DESC LIMIT $' + vals.length, vals);
    res.json(r.rows);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Per-rental amenities, FAQs, house rules & Law 5170 compliance (v11) ─────
// One isolated record per rental, keyed `rental:<id>` in app_data. Binary files
// are NOT stored here — they live in proof_files under month='law5170' and the
// record only keeps their ids, so these rows stay tiny.
function _rentalKey(id) {
  const safe = String(id || '').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 60);
  return safe ? 'rental:' + safe : null;
}
app.get('/api/rental-info/:id', async (req, res) => {
  if (!pool) return res.status(503).json({ error: 'No database configured.' });
  const key = _rentalKey(req.params.id);
  if (!key) return res.status(400).json({ error: 'Invalid rental id.' });
  try {
    const r = await pool.query('SELECT data, updated_at FROM app_data WHERE key = $1', [key]);
    if (!r.rows[0]) return res.json({ amenities: {}, faqs: [], houseRules: {}, compliance: {}, updated: null });
    res.json({ ...r.rows[0].data, updated: r.rows[0].updated_at });
  } catch (e) {
    console.error('[rental-info] read error:', e.message);
    res.status(500).json({ error: 'Read failed.' });
  }
});
app.post('/api/rental-info/:id', async (req, res) => {
  if (!pool) return res.status(503).json({ error: 'No database configured.' });
  const key = _rentalKey(req.params.id);
  if (!key) return res.status(400).json({ error: 'Invalid rental id.' });
  try {
    const body = req.body || {};
    const clean = {
      amenities: (body.amenities && typeof body.amenities === 'object') ? body.amenities : {},
      faqs: Array.isArray(body.faqs) ? body.faqs.filter(f => f && (f.q || f.a)).slice(0, 200) : [],
      houseRules: (body.houseRules && typeof body.houseRules === 'object') ? body.houseRules : {},
      compliance: (body.compliance && typeof body.compliance === 'object') ? body.compliance : {},
    };
    await pool.query(
      `INSERT INTO app_data (key, data, updated_at) VALUES ($1, $2, NOW())
       ON CONFLICT (key) DO UPDATE SET data = $2, updated_at = NOW()`,
      [key, clean]
    );
    logEvent(req, 'pinfo', 'save', req.params.id + ' · ' +
      Object.values(clean.amenities).filter(a => a && a.on).length + ' amenities · ' +
      clean.faqs.length + ' FAQs · ' + Object.keys(clean.compliance).length + ' compliance items');
    res.json({ ok: true });
  } catch (e) {
    console.error('[rental-info] write error:', e.message);
    res.status(500).json({ error: 'Save failed.' });
  }
});
